import 'dart:async';
import 'dart:convert';
import 'dart:math';
import 'package:flutter/material.dart';
import '../../modules/home/widgets/full_desktop_dialog.dart';
import '../../modules/home/widgets/full_desktop_palette.dart';
import '../presentation/quant_application_binding.dart';
import '../presentation/quant_workbench_theme.dart';
import 'binding.dart';
import 'dataset.dart';
import 'editor.dart';
import 'example.dart';
import 'service.dart';
import 'store.dart';
import 'visual_adapter.dart';

/// Panel owns only its draft and subscription. The app owns runs and storage.
class FqeWorkbenchPanel extends StatefulWidget {
  const FqeWorkbenchPanel(
      {super.key,
      this.owner,
      this.visualDocument,
      this.onVisualConfiguration,
      this.showResults = false});
  final Map<String, dynamic> Function()? visualDocument;
  final bool showResults;
  final void Function(String, Object)? onVisualConfiguration;
  final FqeApplicationService? owner;
  @override
  State<FqeWorkbenchPanel> createState() => _FqeWorkbenchPanelState();
}

class _FqeWorkbenchPanelState extends State<FqeWorkbenchPanel> {
  FqeApplicationService? get owner =>
      widget.owner ?? FqeApplicationBinding.service;
  late Map<String, dynamic> _input = fqeExample();
  final _name = TextEditingController(text: '本地 MACD / RSI');
  final _source = TextEditingController();
  final _quantity = TextEditingController(text: '1.000');
  final _cashCap = TextEditingController(text: '1000.00');
  final _capital = TextEditingController();
  final _fee = TextEditingController();
  bool _visual = true;
  bool get _fromGraph => widget.visualDocument != null && _visual;
  String _selectionId() => jsonEncode([
        _fromGraph ? fqeVisualId(widget.visualDocument!()) : 'portable',
        _quantity.text,
        _cashCap.text,
        _capital.text,
        _fee.text,
        _dataset,
        _synthetic,
        _start.text,
        _end.text,
        _warmup.text,
        Map<String, String>.from(_parameterEdits)
      ]);
  final _model = TextEditingController();
  final _start = TextEditingController(),
      _end = TextEditingController(),
      _warmup = TextEditingController(text: '0');
  StreamSubscription<void>? _subscription;
  String? _error, _dataset, _draftId;
  final _parameterEdits = <String, String>{};
  bool _busy = false, _cancelPreparation = false;
  int _revision = 0, _page = 0;
  String _section = 'fills';
  bool _synthetic = true;
  @override
  void initState() {
    super.initState();
    final saved = owner?.editorState;
    if (saved != null) {
      _input = fqeJson(jsonEncode(saved['input']));
      _name.text = saved['name'];
      _dataset = saved['dataset'];
      _draftId = saved['draft_id'];
      _synthetic = saved['inline_csv'];
      _start.text = saved['start'];
      _end.text = saved['end'];
      _warmup.text = saved['warmup'];
      _visual = saved['visual'] ?? true;
      _quantity.text = saved['quantity'] ?? '1.000';
      _cashCap.text = saved['cash_cap'] ?? '1000.00';
    }
    if (widget.visualDocument != null) {
      final config = widget.visualDocument!()['configuration'];
      _capital.text = '${config['initialCapital']}';
      _fee.text = '${config['fee']}';
      if (saved?['visual_document_id'] ==
          fqeVisualId(widget.visualDocument!())) {
        _capital.text = saved?['capital_edit'] ?? _capital.text;
        _fee.text = saved?['fee_edit'] ?? _fee.text;
      }
    }
    _syncText();
    if (saved != null) {
      _source.text = saved['source'];
      _model.text = saved['model'];
      _parameterEdits
          .addAll(Map<String, String>.from(saved['parameter_edits'] ?? {}));
    }
    _subscription = owner?.changes.listen((_) {
      if (mounted) setState(() {});
    });
  }

  void _syncText() {
    _parameterEdits.clear();
    _source.text = const JsonEncoder.withIndent('  ').convert(_input);
    _model.text =
        const JsonEncoder.withIndent('  ').convert(fqeJson(_input['model']));
    _revision++;
  }

  Future<void> _work(Future<void> Function() run) async {
    if (_busy) return;
    setState(() {
      _busy = true;
      _error = null;
    });
    try {
      await run();
    } catch (e) {
      if (mounted) setState(() => _error = '$e');
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  @override
  void dispose() {
    _subscription?.cancel();
    owner?.editorState = {
      'visual_document_id': widget.visualDocument == null
          ? null
          : fqeVisualId(widget.visualDocument!()),
      'capital_edit': _capital.text,
      'fee_edit': _fee.text,
      'visual': _visual,
      'quantity': _quantity.text,
      'cash_cap': _cashCap.text,
      'input': _input,
      'name': _name.text,
      'dataset': _dataset,
      'draft_id': _draftId,
      'inline_csv': _synthetic,
      'start': _start.text,
      'end': _end.text,
      'warmup': _warmup.text,
      'source': _source.text,
      'model': _model.text,
      'parameter_edits': Map<String, String>.from(_parameterEdits)
    };
    for (final c in [
      _name,
      _source,
      _model,
      _start,
      _end,
      _warmup,
      _quantity,
      _cashCap,
      _capital,
      _fee
    ]) {
      c.dispose();
    }
    super.dispose();
  }

  Widget _text(String text, {bool error = false}) => SelectableText(text,
      style: TextStyle(
          fontSize: 11,
          color: error ? FullDesktopPalette.red : FullDesktopPalette.text));
  Widget _button(String label, Future<void> Function() run,
          {bool primary = false, bool enabled = true}) =>
      TextButton(
          onPressed: !_busy && enabled ? () => _work(run) : null,
          style: primary
              ? TextButton.styleFrom(
                  backgroundColor: FullDesktopPalette.action,
                  foregroundColor: FullDesktopPalette.onAction)
              : null,
          child: Text(label));
  void _commitParameters() {
    if (_parameterEdits.isEmpty) return;
    var candidate = _input;
    for (final entry in _parameters) {
      final text = _parameterEdits[entry['key']];
      if (text != null) candidate = fqeSetParameter(candidate, entry, text);
    }
    _input = candidate;
    _syncText();
  }

  void _commitVisualConfiguration() {
    if (!_fromGraph) return;
    final type = {
      'version': 1,
      'shape': 'scalar',
      'kind': 'decimal',
      'scale': 2,
      'unit': {'kind': 'ratio'}
    };
    fqeTypedValue({...type, 'scale': 6}, _capital.text);
    fqeTypedValue(type, _fee.text);
    widget.onVisualConfiguration?.call('initialCapital', _capital.text);
    widget.onVisualConfiguration?.call('fee', _fee.text);
  }

  Future<void> _prepareInput() async {
    _commitVisualConfiguration();
    if (!_fromGraph) _commitParameters();
    final selection = _selectionId();
    final document = _fromGraph
        ? jsonDecode(jsonEncode(widget.visualDocument!()))
            as Map<String, dynamic>
        : null;
    if (document != null) {
      document['configuration']['initialCapital'] = _capital.text;
      document['configuration']['fee'] = _fee.text;
    }
    var input = document != null && _synthetic
        ? fqeVisualSynthetic(document)
        : fqeJson(jsonEncode(_input));
    if (!_synthetic) {
      final datasets = QuantApplicationBinding.service?.datasets;
      if (datasets == null || _dataset == null) {
        throw StateError('请先在数据管理导入并选择行情');
      }
      final snapshot = await datasets.freezeRun(
          _dataset!, 'fqe.${DateTime.now().microsecondsSinceEpoch}', range: {
        'start': _start.text,
        'end': _end.text,
        'warmup_bars': int.parse(_warmup.text)
      });
      input = fqeDatasetInput(
          snapshot, input, _start.text, _end.text, _warmup.text);
    }
    if (document != null) {
      final catalog = await owner!.inspect(fqeExample());
      input = fqeVisualInput(document, input, catalog['descriptors'],
          quantity: _quantity.text, cashCap: _cashCap.text);
    }
    if (selection != _selectionId()) throw StateError('准备期间草稿或配置已修改，请重新校验');
    await owner!.inspect(input);
    await owner!.preflight(input);
    if (selection != _selectionId()) throw StateError('校验期间草稿或配置已修改，请重新校验');
    _input = input;
    if (document != null) _name.text = document['name'];
    _syncText();
  }

  Future<void> _validate() => _prepareInput();

  Future<void> _startRun() async {
    _cancelPreparation = false;
    if (!_fromGraph) _commitParameters();
    _commitVisualConfiguration();
    final selection = _selectionId();
    await _prepareInput();
    final frozen = fqeJson(jsonEncode(_input));
    if (_cancelPreparation) throw StateError('准备阶段已取消');
    if (!mounted) return;
    final yes = await showFullDesktopDialog<bool>(context,
        title: '确认本地回测',
        subtitle: '仅在本机运行 · FQE 原生账本 · 含预热最多 256 根',
        content: SizedBox(
            width: 620,
            height: 280,
            child: SingleChildScrollView(
                child: _text(
                    '模型：${owner!.lastInspection!['execution_id']}\n参数：${_input['parameters']}\n'
                    '范围：${_input['start_ns']} ≤ UTC ns < ${_input['end_ns']}\n预热：${_input['warmup_bars']}\n'
                    '资金与成本：${jsonEncode(_input['account'])}\n订单规则：${jsonEncode(_input['policies'])}\n'
                    '数据：${_synthetic ? '公开合成输入；运行后才产生结果' : _dataset}\n'
                    '修改草稿不会影响本次运行；旧 Python / Dart 记录继续使用原读取器。'))),
        confirmLabel: '开始回测',
        onConfirm: () => true);
    if (yes == true) {
      if (_cancelPreparation || selection != _selectionId()) {
        throw StateError('确认期间草稿或配置已修改，请重新校验并确认');
      }
      await owner!.start(frozen, name: _name.text);
    }
  }

  List<Map<String, dynamic>> get _parameters {
    try {
      return fqeParameterEntries(_input);
    } catch (_) {
      return [];
    }
  }

  Widget _parametersForm() {
    final values = fqeJson(_input['parameters'])['values'];
    return Wrap(spacing: 10, runSpacing: 10, children: [
      for (final entry in _parameters)
        SizedBox(
            width: 240,
            child: TextFormField(
                key: ValueKey('$_revision.${entry['key']}'),
                initialValue: _parameterEdits[entry['key']] ??
                    (values[entry['key']] != null
                        ? fqeDisplayValue(values[entry['key']])
                        : entry['default'] != null
                            ? fqeDisplayValue(entry['default'])
                            : ''),
                decoration: InputDecoration(
                    labelText: '${entry['key']} · ${entry['type']['kind']}',
                    helperText:
                        '${entry['description'] ?? ''} ${entry['type']['unit'] ?? ''} · 保存、校验或运行时应用当前输入'),
                onChanged: (text) => _parameterEdits[entry['key']] = text,
                onFieldSubmitted: (_) => _work(_validate)))
    ]);
  }

  Future<void> _compose(Map<String, dynamic> descriptor) async {
    _commitParameters();
    final node = TextEditingController(text: 'node${Random().nextInt(10000)}');
    final params = <String, TextEditingController>{};
    final connections = <String, dynamic>{};
    for (final p in descriptor['parameters']['entries']) {
      params[p['key']] = TextEditingController(
          text: p['default'] == null ? '' : fqeDisplayValue(p['default']));
    }
    try {
      final yes = await showFullDesktopDialog<bool>(context,
          title: '添加描述项节点',
          subtitle:
              '${descriptor['key']['id']} @ ${descriptor['key']['version']}',
          content: SizedBox(
              width: 580,
              height: 360,
              child: SingleChildScrollView(
                  child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                    _text('${descriptor['semantics']}'),
                    const SizedBox(height: 12),
                    TextField(
                        controller: node,
                        decoration: const InputDecoration(labelText: '节点标识')),
                    for (final p in descriptor['parameters']['entries'])
                      Padding(
                          padding: const EdgeInsets.only(top: 10),
                          child: TextField(
                              controller: params[p['key']],
                              decoration: InputDecoration(
                                  labelText:
                                      '${p['key']} · ${p['type']['kind']}',
                                  helperText: '${p['description']}'))),
                    for (final port in descriptor['inputs'])
                      Padding(
                          padding: const EdgeInsets.only(top: 10),
                          child: DropdownButtonFormField<String>(
                              isExpanded: true,
                              decoration: InputDecoration(
                                  labelText: '输入 ${port['name']} · 精确类型连接'),
                              items: [
                                for (final source
                                    in fqeSources(_input, port['type']))
                                  DropdownMenuItem(
                                      value: jsonEncode(source['source']),
                                      child: Text(source['label']))
                              ],
                              onChanged: (v) {
                                if (v != null) {
                                  connections[port['name']] = jsonDecode(v);
                                }
                              })),
                    _text(
                        '输出：${jsonEncode(descriptor['outputs'])}\n添加后会生成公开图端口与事件输出，原生校验通过后提交。'),
                  ]))),
          confirmLabel: '校验并添加',
          onConfirm: () => true);
      if (yes != true) return;
      final candidate = fqeCompose(_input, descriptor, node.text,
          {for (final e in params.entries) e.key: e.value.text}, connections);
      await owner!.inspect(candidate);
      _input = candidate;
      _syncText();
    } finally {
      node.dispose();
      for (final p in params.values) {
        p.dispose();
      }
    }
  }

  Widget _descriptors() {
    final inspected = owner?.lastInspection;
    if (inspected == null) return _text('点击“校验与发现”读取内置引擎的实际参数、端口和描述项。');
    return Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
      _text(
          '执行身份：${inspected['execution_id']}\n注册表：${inspected['registry_id']}'),
      for (final d in inspected['descriptors'])
        ExpansionTile(
            title: Text('${d['key']['id']} @ ${d['key']['version']}',
                style: const TextStyle(fontSize: 12)),
            subtitle: Text('${d['category']} · ${d['purity']}',
                style: const TextStyle(fontSize: 10)),
            children: [
              Padding(
                  padding: const EdgeInsets.all(10),
                  child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        _text(
                            '${d['semantics']}\n参数：${jsonEncode(d['parameters'])}\n'
                            '输入：${jsonEncode(d['inputs'])}\n输出：${jsonEncode(d['outputs'])}'),
                        _button('配置并组合',
                            () => _compose(Map<String, dynamic>.from(d)),
                            enabled: !_fromGraph && _input['kind'] == 'event'),
                      ]))
            ]),
    ]);
  }

  Widget _results() {
    final service = owner!, report = service.report;
    final sections = [
      'observations',
      'decisions',
      'orders',
      'fills',
      'journal',
      'execution_events',
      'equity_curve'
    ];
    final rows = report?[_section] as List? ?? [];
    final pages = max(1, (rows.length / 16).ceil());
    final page = min(_page, pages - 1);
    return Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
      _text(
          '当前记录：${service.current?['name'] ?? '尚无运行'} · ${service.current?['phase'] ?? service.view?.phase ?? '就绪'}\n'
          '输入身份：${service.current?['input_id'] ?? '—'}\n结果身份：${service.current?['result_id'] ?? '—'}'),
      if (service.busy) const LinearProgressIndicator(),
      if (service.busy) _text('计算中；实际处理数量在原生结果提交后显示。关闭此面板不会停止任务。'),
      if (report != null) ...[
        _text(
            '实际处理：${report['processed_source_bars']} 根 · ${report['terminal']}\n'
            '指标：${jsonEncode(report['metrics'])}\n账户：${jsonEncode(report['account'])}\n'
            '参数：${jsonEncode(report['manifest']['bound_parameters'])}'),
        Wrap(spacing: 8, children: [
          for (final s in sections)
            ChoiceChip(
                label: Text(s),
                selected: s == _section,
                onSelected: (_) => setState(() {
                      _section = s;
                      _page = 0;
                    }))
        ]),
        for (final row in rows.skip(page * 16).take(16))
          Padding(
              padding: const EdgeInsets.symmetric(vertical: 5),
              child: _text(jsonEncode(row))),
        Wrap(spacing: 8, children: [
          TextButton(
              onPressed:
                  page > 0 ? () => setState(() => _page = page - 1) : null,
              child: const Text('上一页')),
          Text('${page + 1}/$pages · ${rows.length} 条'),
          TextButton(
              onPressed: page < pages - 1
                  ? () => setState(() => _page = page + 1)
                  : null,
              child: const Text('下一页'))
        ]),
      ],
      const Divider(),
      _text('本地历史（只读打开，不重新运行）'),
      for (final item in service.history)
        ListTile(
            dense: true,
            title: Text(
                '${item['name'] ?? item['id']} · ${item['phase'] ?? '记录损坏'}'),
            subtitle: Text('${item['error'] ?? item['created'] ?? ''}'),
            onTap: service.busy
                ? null
                : () => _work(() => service.openResult(item['id']))),
    ]);
  }

  @override
  Widget build(BuildContext context) {
    final service = owner;
    if (service == null) {
      return Center(
          child: _text(FqeApplicationBinding.failure ?? '本机 FQE 服务未初始化'));
    }
    final datasets = QuantApplicationBinding.service?.datasets.items ??
        <Map<String, dynamic>>[];
    return Theme(
        data: quantWorkbenchTheme(context),
        child: DefaultTabController(
            length: 3,
            initialIndex: widget.showResults ? 2 : 0,
            child: Column(children: [
              const TabBar(tabs: [
                Tab(text: '模型与参数'),
                Tab(text: '描述项与组合'),
                Tab(text: '运行与结果')
              ]),
              if (_error != null || service.failure != null)
                Padding(
                    padding: const EdgeInsets.all(8),
                    child: _text(_error ?? service.failure!, error: true)),
              Padding(
                  padding: const EdgeInsets.symmetric(horizontal: 10),
                  child: Wrap(spacing: 8, runSpacing: 4, children: [
                    _button('校验与发现', _validate),
                    _button('保存策略', () async {
                      await _prepareInput();
                      _draftId = await service.saveDraft(_name.text, _input);
                    }),
                    _button('开始回测', _startRun,
                        primary: true, enabled: !service.busy),
                    TextButton(
                        onPressed: service.busy || _busy
                            ? () async {
                                _cancelPreparation = true;
                                try {
                                  await service.stop();
                                } catch (e) {
                                  if (mounted) setState(() => _error = '$e');
                                }
                              }
                            : null,
                        child: const Text('停止')),
                  ])),
              Expanded(
                  child: TabBarView(children: [
                ListView(padding: const EdgeInsets.all(12), children: [
                  if (widget.visualDocument != null) ...[
                    DropdownButtonFormField<bool>(
                        value: _visual,
                        decoration: const InputDecoration(labelText: '执行模型来源'),
                        items: const [
                          DropdownMenuItem(
                              value: true, child: Text('当前节点图（严格映射）')),
                          DropdownMenuItem(
                              value: false, child: Text('独立可移植模型（显式导入或公开模板）'))
                        ],
                        onChanged: (v) {
                          if (v != null) {
                            setState(() {
                              _visual = v;
                              _error = null;
                              _draftId = null;
                            });
                          }
                        }),
                    const SizedBox(height: 12),
                    _text(_fromGraph
                        ? '运行前冻结当前节点与参数；代码编辑中的 Python 不在本次执行范围。支持 EMA/SMA、Wilder RSI、MACD、AND/OR、现金做多市价单。参数注册表的绑定值取节点快照，未绑定参数不参与执行。风险管理/BOLL/限价/做空/Tick 等未映射配置会阻止运行。条件不成立不自动平仓，未平仓持仓按期末价格估值。'
                        : '此模型独立于节点画布和 Python 源码，运行与保存均以此处明确导入的输入为准。'),
                    if (_fromGraph) ...[
                      TextField(
                          controller: _capital,
                          decoration: const InputDecoration(
                              labelText: '初始资金（报价币，精确十进制）')),
                      TextField(
                          controller: _fee,
                          decoration: const InputDecoration(
                              labelText: '手续费 (%)，最多 2 位小数')),
                      TextField(
                          controller: _quantity,
                          decoration: const InputDecoration(
                              labelText: '每次开仓固定数量（精确十进制）')),
                      TextField(
                          controller: _cashCap,
                          decoration: const InputDecoration(
                              labelText: '单次开仓现金上限（报价币）')),
                    ],
                  ],
                  _text(
                      'FQE 原生引擎 · 本地离线 · cash_long / margin_long · 有界历史最多 256 根含预热\n'
                      '节点模式冻结当前草稿与可见资金配置；可移植模式使用其精确输入。支持范围以原生预检为准。'),
                  const SizedBox(height: 12),
                  TextField(
                      controller: _name,
                      decoration: const InputDecoration(labelText: '策略名称')),
                  const SizedBox(height: 12),
                  DropdownButtonFormField<String>(
                      value: _draftId,
                      isExpanded: true,
                      decoration: const InputDecoration(
                          labelText: '已保存策略（读取精确参数与冻结输入）'),
                      items: [
                        for (final d in service.drafts)
                          DropdownMenuItem(
                              value: d['id'],
                              child: Text('${d['name'] ?? d['id']}'))
                      ],
                      onChanged: (v) {
                        if (v != null) {
                          _work(() async {
                            final draft = await service.loadDraft(v);
                            _visual = false;
                            _input = draft['input'];
                            _name.text = draft['name'];
                            _draftId = v;
                            _synthetic = true;
                            _syncText();
                          });
                        }
                      }),
                  const SizedBox(height: 12),
                  if (!_fromGraph) _parametersForm(),
                  const SizedBox(height: 12),
                  SwitchListTile(
                      dense: true,
                      title: Text(
                          _fromGraph ? '使用明确标记的公开合成行情' : '使用当前输入中的 CSV 与历史说明'),
                      subtitle: Text(_fromGraph
                          ? '开启为显式公开合成 240 根输入（USD，价格 2 位、数量 3 位）；关闭后冻结数据管理的真实历史。节点产品和周期必须匹配。'
                          : '初始模板为公开合成行情。关闭后从数据管理冻结所选范围。'),
                      value: _synthetic,
                      onChanged: (v) => setState(() => _synthetic = v)),
                  if (!_synthetic) ...[
                    DropdownButtonFormField<String>(
                        value: _dataset,
                        isExpanded: true,
                        decoration:
                            const InputDecoration(labelText: '数据管理中的已保存行情'),
                        items: [
                          for (final d in datasets)
                            DropdownMenuItem(
                                value: d['dataset_id'],
                                child: Text(
                                    '${d['instrument_id']} ${d['timeframe']} ${d['dataset_id']}'))
                        ],
                        onChanged: (v) => setState(() {
                              _dataset = v;
                              final d = datasets
                                  .firstWhere((d) => d['dataset_id'] == v);
                              _start.text = d['first_open'];
