/// Versioned import of the existing visual schema, not an indicator registry.
/// Native descriptors remain authoritative; unfamiliar providers use portable IR.
String fqeVisualSource(Map<String, dynamic> document) => jsonEncode({
      'schemaVersion': document['schemaVersion'],
      'name': document['name'],
      'nodes': [
        for (final n in document['nodes'])
          {'id': n['id'], 'kind': n['kind'], 'parameters': n['parameters']}
      ],
      'edges': document['edges'],
      'configuration': document['configuration'],
      'parameterRegistry': document['parameterRegistry'],
    });
String fqeVisualId(Map<String, dynamic> document) =>
    'sha256:${fqeHash(utf8.encode(fqeVisualSource(document)))}';

/// Explicit synthetic input, never a market-data substitution or a result.
Map<String, dynamic> fqeVisualSynthetic(Map<String, dynamic> document) {
  final bars = (document['nodes'] as List).where((n) => n['kind'] == 'bars');
  if (bars.length != 1) throw StateError('节点图需要且只能有一个 K 线数据节点');
  final p = bars.single['parameters'];
  final symbol = '${p['symbol']}';
  if (!RegExp(r'^[A-Za-z0-9:._-]{1,48}$').hasMatch(symbol)) {
    throw StateError('合成输入的产品标识无效');
  }
  final seconds = <String, int>{
    '1m': 60,
    '5m': 300,
    '15m': 900,
    '1h': 3600,
    '4h': 14400,
    '1d': 86400
  }[p['timeframe']];
  if (seconds == null) throw StateError('合成输入暂不支持此周期，请选择真实历史数据');
  final input = fqeExample(), spec = fqeJson(input['history_spec']);
  final start = DateTime.utc(2024, 1, 2),
      end = start.add(Duration(seconds: seconds * 240));
  String stamp(DateTime d) => d.toIso8601String().replaceFirst('.000Z', 'Z');
  spec['instrument']['id'] = symbol;
  spec['timeframe'] = {
    'id': p['timeframe'],
    'duration_ns': '${BigInt.from(seconds) * BigInt.from(1000000000)}'
  };
  spec['calendar']['sessions'] = [
    {'open': stamp(start), 'close': stamp(end)}
  ];
  spec['acquired_at'] = stamp(end.add(const Duration(seconds: 1)));
  spec['performance_start'] = stamp(start);
  spec['source']['label'] = 'public.synthetic.visual-adapter.v1';
  final csv = StringBuffer(
      'instrument_id,timeframe,open_time,close_time,open,high,low,close,volume,is_closed\n');
  for (var i = 0; i < 240; i++) {
    final price = 100 + (i % 40 < 20 ? i % 20 : 20 - i % 20);
    csv.writeln(
        '$symbol,${p['timeframe']},${stamp(start.add(Duration(seconds: seconds * i)))},${stamp(start.add(Duration(seconds: seconds * (i + 1))))},$price.00,$price.00,$price.00,$price.00,100.000,true');
  }
  input['history_spec'] = jsonEncode(spec);
  input['csv'] = csv.toString();
  input['start_ns'] =
      '${BigInt.from(start.microsecondsSinceEpoch) * BigInt.from(1000)}';
  input['end_ns'] =
      '${BigInt.from(end.microsecondsSinceEpoch) * BigInt.from(1000)}';
  return input;
}

Map<String, dynamic> fqeVisualInput(Map<String, dynamic> document,
    Map<String, dynamic> base, List<dynamic> descriptors,
    {required String quantity, required String cashCap}) {
  Never fail(String text) => throw StateError('节点图无法回测：$text');
  if (document['schemaVersion'] != 1) fail('不支持的草稿版本');
  final nodes = (document['nodes'] as List).cast<Map<String, dynamic>>();
  final edges = (document['edges'] as List).cast<Map<String, dynamic>>();
  if (nodes.length > 16 || nodes.length < 5) fail('需要 5–16 个受支持节点');
  Map<String, dynamic> one(String kind) {
    final matches = nodes.where((n) => n['kind'] == kind);
    if (matches.length != 1) fail('需要且只能有一个 $kind 节点');
    return matches.single;
  }

  final bars = one('bars'),
      condition = one('condition'),
      signal = one('signal'),
      order = one('order');
  final indicators = nodes
      .where((n) => ['ema', 'sma', 'rsi', 'macd'].contains(n['kind']))
      .toList();
  if (indicators.isEmpty || nodes.length != indicators.length + 4) {
    fail('当前支持 EMA / SMA / Wilder RSI / MACD；风险管理、BOLL 或其他节点需版本化实现，不会忽略');
  }
  final ids = nodes.map((n) => n['id']).toSet();
  if (ids.length != nodes.length) fail('节点标识重复');
  final expected = <String>{
    for (final n in indicators) '${bars['id']}→${n['id']}',
    for (final n in indicators) '${n['id']}→${condition['id']}',
    '${condition['id']}→${signal['id']}',
    '${signal['id']}→${order['id']}'
  };
  final actual = edges.map((e) => '${e['from']}→${e['to']}').toSet();
  if (edges.length != expected.length ||
      actual.length != expected.length ||
      !actual.containsAll(expected)) {
    fail('连线必须为 K线→各指标→同一条件→做多开仓信号→市价订单；不能有额外或未连接规则');
  }
  const keys = <String, Set<String>>{
    'bars': {'symbol', 'timeframe', 'source'},
    'ema': {'period', 'slowPeriod', 'price'},
    'sma': {'period', 'slowPeriod', 'price'},
    'rsi': {
      'period',
      'price',
      'method',
      'threshold',
      'RSI',
      'Overbought',
      'Oversold'
    },
    'macd': {'period', 'slowPeriod', 'signalPeriod'},
    'condition': {'operator'},
    'signal': {'direction', 'action'},
    'order': {'orderType', 'validity', 'slippage'}
  };
  for (final n in nodes) {
    if (!(n['parameters'] as Map)
        .keys
        .every((k) => keys[n['kind']]!.contains(k))) fail('${n['id']} 含未映射参数');
  }
  final sp = signal['parameters'],
      op = order['parameters'],
      cp = condition['parameters'];
  if (sp['direction'] != '做多' || sp['action'] != '开仓') fail('只支持现金做多开仓');
  if (op['orderType'] != '市价单' || op['validity'] != 'GTC') {
    fail('只支持下一根开盘成交的市价单 / GTC；不支持限价、IOC、FOK');
  }
  if (!['AND', 'OR'].contains(cp['operator'])) fail('条件只支持 AND / OR');
  final config = document['configuration'];
  if (config['frequency'] != '每根 K 线') fail('只支持已收盘 K 线触发，不支持 Tick');
  if (!['模拟环境', '本地环境'].contains(config['environment'])) fail('只支持本地历史模拟');
  final input = fqeJson(jsonEncode(base)),
      spec = fqeJson(input['history_spec']);
  final instrument = spec['instrument'], bp = bars['parameters'];
  if (bp['symbol'] != instrument['id'] ||
      bp['timeframe'] != spec['timeframe']['id']) {
    fail('K 线产品/周期与所选冻结数据不一致，请明确修改节点绑定');
  }
  if (bp['source'] != '历史行情') fail('数据节点只支持历史行情');
  final model = fqeJson(input['model']), graph = model['graph'];
  final priceType = {
    'version': 1,
    'shape': 'scalar',
    'kind': 'decimal',
    'scale': instrument['price_scale'],
    'unit': {'kind': 'price', 'instrument': instrument['id']}
  };
  final body = <String, dynamic>{
    'inputs': <dynamic>[],
    'nodes': <dynamic>[],
    'outputs': <dynamic>[]
  };
  final entries = <dynamic>[], terms = <Map<String, dynamic>>[];
  Map<String, dynamic> compare(String op, dynamic left, dynamic right) => {
        'binary': {'op': op, 'left': left, 'right': right}
      };
  Map<String, dynamic> output(String id) => {'output': id};
  Map<String, dynamic> add(Map<String, dynamic> n, String suffix,
      Map<String, String> params, String port) {
    final key = 'reference.${n['kind']}';
    final matches = descriptors
        .where((d) => d['key']['id'] == key && d['key']['version'] == '1');
    if (matches.length != 1) fail('引擎没有可用的 $key 描述项');
    final d = matches.single;
    if (!entries.any((e) => e['key']['id'] == key)) {
      entries.add({
        for (final k in ['key', 'artifact', 'descriptor_version', 'role'])
          k: d[k]
      });
    }
    final id = 'v${nodes.indexOf(n)}$suffix';
    final field = {
      '收盘价': 'close',
      '开盘价': 'open',
      '最高价': 'high',
      '最低价': 'low'
    }[n['parameters']['price'] ?? '收盘价'];
    if (field == null) fail('不支持的价格输入');
    final sample = 'sample_$field';
    if (!(body['inputs'] as List).any((p) => p['name'] == sample)) {
      body['inputs'].add({'name': sample, 'type': priceType});
    }
    final arguments = <String, dynamic>{};
    for (final p in d['parameters']['entries']) {
      final text = params[p['key']];
      if (text == null) fail('$key 的描述项参数与适配版本不一致');
      final typed = fqeTypedValue(Map<String, dynamic>.from(p['type']), text);
      if (typed['type']['kind'] != 'u64' ||
          BigInt.parse(typed['value']) <= BigInt.zero) fail('指标周期必须是正整数');
      arguments[p['key']] = {'literal': typed};
    }
    final ports = <dynamic>[];
    for (final p in d['outputs']) {
      final type = fqeJson(jsonEncode(p['type']));
      if (type['unit']?['kind'] == 'price') {
        type['unit']['instrument'] = instrument['id'];
      }
      ports.add({'name': p['name'], 'type': type});
    }
    if (!ports.any((p) => p['name'] == port)) fail('$key 缺少所需输出');
    body['nodes'].add({
      'id': id,
      'target': {'kind': 'provider', 'key': d['key']},
      'arguments': arguments,
      'inputs': [
        {
          'name': 'close',
          'source': {'input': sample}
        }
      ],
      'outputs': ports
    });
    for (final p in ports) {
      body['outputs'].add({
        'name': '${id}_${p['name']}',
        'type': p['type'],
        'source': {'node': id, 'port': p['name']}
      });
    }
    return output('${id}_$port');
  }

  for (final n in indicators) {
    final p = n['parameters'];
    switch (n['kind']) {
      case 'ema':
      case 'sma':
        if ((num.parse('${p['period']}')) >= num.parse('${p['slowPeriod']}')) {
          fail('快周期必须小于慢周期');
        }
        terms.add(compare(
            'greater',
            add(n, 'fast', {'period': '${p['period']}'}, 'value'),
            add(n, 'slow', {'period': '${p['slowPeriod']}'}, 'value')));
        break;
      case 'rsi':
        if (p['method'] != 'Wilder' ||
            p['RSI'] != true ||
            p['Overbought'] != false ||
            p['Oversold'] != false) fail('RSI 只支持 Wilder 数值及显式阈值；其他输出未映射');
        final type = {
          'version': 1,
          'shape': 'scalar',
          'kind': 'decimal',
          'scale': 12,
          'unit': {'kind': 'ratio'}
        };
        final threshold = fqeTypedValue(type, '${p['threshold']}');
        final value = BigInt.parse(threshold['value']);
        if (value < BigInt.zero ||
            value > BigInt.from(100) * BigInt.from(10).pow(12)) {
          fail('RSI 阈值须在 0–100');
        }
        terms.add(compare(
            'less',
            add(n, '', {'period': '${p['period']}'}, 'value'),
            {'literal': threshold}));
        break;
      case 'macd':
        if (num.parse('${p['period']}') >= num.parse('${p['slowPeriod']}')) {
          fail('MACD 快周期必须小于慢周期');
        }
        final left = add(
            n,
            '',
            {
              'fast': '${p['period']}',
              'slow': '${p['slowPeriod']}',
              'signal': '${p['signalPeriod']}'
            },
            'line');
        terms.add(
            compare('greater', left, output('v${nodes.indexOf(n)}_signal')));
        break;
    }
  }
  var decision = terms.first;
  for (final term in terms.skip(1)) {
    decision = compare(cp['operator'] == 'OR' ? 'or' : 'and', decision, term);
  }
  final source = fqeVisualSource(document);
  if (utf8.encode(source).length > 24000 || source.length > 24000) {
    fail('节点来源快照过大');
  }
  graph['id'] = 'desk.visual.graph';
  graph['parameters'] = {'version': 1, 'entries': <dynamic>[]};
  graph['entries'] = entries;
  graph['graph'] = body;
  graph['metadata'] = {
    'visual_adapter': 'desk.visual/1',
    'visual_source_id': fqeVisualId(document),
    for (var i = 0; i < source.length; i += 1000)
      'visual_source_${i ~/ 1000}': source.substring(
          i, i + 1000 > source.length ? source.length : i + 1000)
  };
  model['id'] = 'desk.visual.event';
  model['trigger'] = {
    'kind': 'closed_bar',
    'instrument': instrument['id'],
    'timeframe_ns': spec['timeframe']['duration_ns'],
    'price_scale': instrument['price_scale'],
    'volume_scale': instrument['quantity_scale']
  };
  model['bindings'] = {
    for (final p in body['inputs'])
      p['name']: (p['name'] as String).substring(7)
  };
  model['crossings'] = <dynamic>[];
  model['warmup_samples'] = '0';
  model['outputs'] = [
    {'name': 'decision', 'expression': decision}
  ];
  model['signals'] = [
    {'output': 'decision', 'kind': 'long'}
  ];
  String bps(dynamic value) => '${fqeTypedValue({
            'version': 1,
            'shape': 'scalar',
            'kind': 'decimal',
            'scale': 2,
            'unit': {'kind': 'ratio'}
          }, '$value')['value']}';
  input['model'] = jsonEncode(model);
  input['parameters'] = jsonEncode({'version': 1, 'values': {}});
  input['account'] = {
    'id': 'local.research',
    'profile': 'cash_long',
    'initial_cash': '${config['initialCapital']}',
    'participation_bps': '10000',
    'fee_bps': bps(config['fee']),
    'minimum_fee': '0',
    'slippage_bps': bps(op['slippage']),
    'risk': null
  };
  input['policies'] = [
    {
      'id': 'entry',
      'source': {'kind': 'long_signal'},
      'action': {
        'kind': 'buy_if_flat',
        'quantity': quantity,
        'cash_cap': cashCap
      }
    }
  ];
  return input;
}

