void check(bool ok, String label) {
  if (!ok) throw StateError(label);
}

Map<String, dynamic> graph() => {
      'schemaVersion': 1,
      'name': '视觉 RSI 原生回测',
      'nodes': [
        {
          'id': 'bars',
          'kind': 'bars',
          'parameters': {
            'symbol': 'BTCUSDT',
            'timeframe': '15m',
            'source': '历史行情'
          }
        },
        {
          'id': 'rsi',
          'kind': 'rsi',
          'parameters': {
            'period': 2,
            'threshold': 100,
            'price': '收盘价',
            'method': 'Wilder',
            'RSI': true,
            'Overbought': false,
            'Oversold': false
          }
        },
        {
          'id': 'condition',
          'kind': 'condition',
          'parameters': {'operator': 'AND'}
        },
        {
          'id': 'signal',
          'kind': 'signal',
          'parameters': {'direction': '做多', 'action': '开仓'}
        },
        {
          'id': 'order',
          'kind': 'order',
          'parameters': {'orderType': '市价单', 'validity': 'GTC', 'slippage': 0}
        },
      ],
      'edges': [
        {'from': 'bars', 'to': 'rsi'},
        {'from': 'rsi', 'to': 'condition'},
        {'from': 'condition', 'to': 'signal'},
        {'from': 'signal', 'to': 'order'}
      ],
      'configuration': {
        'initialCapital': '10000.00',
        'fee': '0',
        'environment': '模拟环境',
        'frequency': '每根 K 线',
        'trials': 100
      },
      'parameterRegistry': [],
    };
Future<void> main(List<String> args) async {
  final temp = await Directory.systemTemp.createTemp('fqe-visual-');
  final pin = jsonDecode(await File('ci/fqe-engine.json').readAsString());
  final service = FqeApplicationService(
      FqeStore(temp),
      '${Directory.current.path}/.dart_tool/fqe-prepared/fqe-desktop-peer',
      {...pin, 'executable_sha256': pin['prepared_sha256']});
  final proof = <String, dynamic>{
    'format': 'finger-desk.fqe-visual-evidence/1',
    'checks': <String>[]
  };
  await service.initialize();
  try {
    final catalog = await service.inspect(fqeExample());
    Map<String, dynamic> convert(Map<String, dynamic> d) =>
        fqeVisualInput(d, fqeVisualSynthetic(d), catalog['descriptors'],
            quantity: '1.000', cashCap: '1000.00');
    Future<void> idle() async {
      final clock = Stopwatch()..start();
      while (service.busy) {
        if (clock.elapsedMilliseconds > 5000) throw StateError('timeout');
        await Future<void>.delayed(const Duration(milliseconds: 5));
      }
      check(service.failure == null, '${service.failure}');
    }

    final first = convert(graph());
    await service.preflight(first);
    final saved = await service.saveDraft('视觉来源', first);
    check(
        fqeInputId((await service.loadDraft(saved))['input']) ==
            fqeInputId(first),
        'saved exact visual input');
    await service.start(first, name: 'visual.100');
    await idle();
    final report = service.report!;
    check(
        report['processed_source_bars'] == '240' ||
            report['processed_source_bars'] == 240,
        '240 actual bars');
    check((report['fills'] as List).isNotEmpty,
        '100 threshold produces native fill');
    check(
        report['metrics']['initial_equity'] == '10000.00' &&
            report['metrics']['final_equity'] == '9983.00',
        'independent one-lot cash outcome');
    check(
        report['fills'][0]['price'] == '118.00' &&
            report['fills'][0]['quantity'] == '1.000',
        'independent next-open entry');
    proof['positive'] = {
      'input_id': fqeInputId(first),
      'result_id': service.current!['result_id'],
      'metrics': report['metrics'],
      'account': report['account'],
      'fills': report['fills']
    };
    final changed = graph();
    changed['nodes'][1]['parameters']['threshold'] = 0;
    await service.start(convert(changed), name: 'visual.0');
    await idle();
    check((service.report!['fills'] as List).isEmpty,
        'zero RSI threshold cannot enter');
    check(fqeVisualId(changed) != fqeVisualId(graph()),
        'source parameter changes identity');
    check(service.report!['metrics']['final_equity'] == '10000.00',
        'zero threshold preserves cash');
    proof['zero_threshold'] = {
      'result_id': service.current!['result_id'],
      'metrics': service.report!['metrics'],
      'account': service.report!['account']
    };
    final restored = service.history.first['id'];
    await service.openResult(restored);
    (proof['checks'] as List).cast<String>().addAll(<String>[
      'actual.native.240-bars',
      'two.threshold.variants',
      'exact.save.reselect',
      'history.readonly',
      'source.parameter.identity'
    ]);
    for (final kind in ['ema', 'sma', 'macd']) {
      final d = graph();
      d['nodes'][1]['kind'] = kind;
      d['nodes'][1]['parameters'] = kind == 'macd'
          ? {'period': 2, 'slowPeriod': 3, 'signalPeriod': 2}
          : {'period': 2, 'slowPeriod': 3, 'price': '开盘价'};
      final candidate = convert(d);
      await service.preflight(candidate);
      await service.start(candidate, name: 'visual.$kind');
      await idle();
      check(
          (service.report!['fills'] as List).isNotEmpty, 'native $kind entry');
      (proof['checks'] as List).add('actual.native.$kind');
    }
    final combined = graph();
    combined['nodes'].add({
      'id': 'mean',
      'kind': 'sma',
      'parameters': {'period': 2, 'slowPeriod': 3, 'price': '最高价'}
    });
    combined['edges'].addAll(<Map<String, String>>[
      {'from': 'bars', 'to': 'mean'},
      {'from': 'mean', 'to': 'condition'}
    ]);
    for (final op in ['AND', 'OR']) {
      combined['nodes'][2]['parameters']['operator'] = op;
      await service.start(convert(combined), name: 'visual.$op');
      await idle();
      check(service.report!['terminal'] == 'completed', 'native combined $op');
      (proof['checks'] as List).add('actual.native.$op');
    }
    final cases = <String, void Function(Map<String, dynamic>)>{
      'limit': (d) => d['nodes'][4]['parameters']['orderType'] = '限价单',
      'risk': (d) => (d['nodes'] as List).add({
            'id': 'risk',
            'kind': 'risk',
            'parameters': {'stopLoss': 1.5}
          }),
      'rsi.ema': (d) => d['nodes'][1]['parameters']['method'] = 'EMA',
      'unknown.parameter': (d) => d['nodes'][1]['parameters']['newRule'] = true,
      'unmapped.edge': (d) =>
          (d['edges'] as List).add({'from': 'bars', 'to': 'condition'}),
      'short': (d) => d['nodes'][3]['parameters']['direction'] = '做空',
      'tick': (d) => d['configuration']['frequency'] = '每个 Tick',
      'invalid.period': (d) => d['nodes'][1]['parameters']['period'] = 2.5,
      'invalid.threshold': (d) =>
          d['nodes'][1]['parameters']['threshold'] = 101,
    };
    for (final item in cases.entries) {
      final d = graph();
      item.value(d);
      var rejected = false;
      try {
        await service.preflight(convert(d));
      } catch (_) {
        rejected = true;
      }
      check(rejected, 'reject ${item.key}');
      (proof['checks'] as List).add('reject.${item.key}');
    }
    final mismatch = graph(), base = fqeVisualSynthetic(graph());
    mismatch['nodes'][0]['parameters']['symbol'] = 'OTHER';
    var rejected = false;
    try {
      fqeVisualInput(mismatch, base, catalog['descriptors'],
          quantity: '1', cashCap: '1000');
    } catch (_) {
      rejected = true;
    }
    check(rejected, 'reject dataset binding mismatch');
    (proof['checks'] as List).add('reject.dataset.binding');
    proof['pass'] = true;
    proof['completed_at'] = DateTime.now().toUtc().toIso8601String();
    await File(args.single)
        .writeAsString(const JsonEncoder.withIndent('  ').convert(proof));
    stdout.writeln('PASS ${proof['checks'].length} visual/native checks');
  } finally {
    await service.shutdown();
    await temp.delete(recursive: true);
  }
}

import 'dart:async';
import 'dart:convert';
import 'dart:io';
import 'package:finger_desk/app/quant/fqe/offline_research.dart';
import 'package:finger_desk/app/quant/fqe/panel.dart';
import 'package:finger_desk/app/quant/fqe/service.dart';
import 'package:finger_desk/app/quant/fqe/store.dart';
import 'package:finger_desk/app/modules/home/widgets/full_desktop_dialog.dart';
import 'package:finger_desk/app/modules/home/widgets/quant_visual_strategy_editor.dart';
import 'package:finger_desk/app/modules/home/workbench/strategy/visual_strategy_document.dart';
import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:get/get.dart';
import '../fqe_visual_check.dart' as visual;

class _RenderService extends FqeApplicationService {
  _RenderService() : super(FqeStore(Directory('/unused')), '/unused', {});
  Map<String, dynamic>? started;
  Completer<void>? preparation;
  @override
  Future<Map<String, dynamic>> inspect(Map<String, dynamic> input) async {
    lastInspection =
        jsonDecode(File('test/quant/fqe-descriptors.json').readAsStringSync());
    return lastInspection!;
  }

  @override
  Future<Map<String, dynamic>> preflight(Map<String, dynamic> input) async {
    await preparation?.future;
    return {};
  }

  @override
  Future<void> start(Map<String, dynamic> input, {String name = '本地回测'}) async {
    started = input;
  }
}

void main() {
  testWidgets(
      'graph default rejects unsupported rules; visible exact configuration commits without Enter',
      (tester) async {
    final service = _RenderService(), d = visual.graph();
    Widget app() => GetMaterialApp(
        locale: const Locale('zh', 'CN'),
        home: Scaffold(
            body: FqeWorkbenchPanel(
                owner: service,
                visualDocument: () => d,
                onVisualConfiguration: (k, v) => d['configuration'][k] = v)));
    await tester.pumpWidget(app());
    final capital = find.widgetWithText(TextField, '初始资金（报价币，精确十进制）');
    await tester.ensureVisible(capital);
    await tester.enterText(capital, '1234.56');
    await tester.tap(find.text('开始回测'));
    await tester.pumpAndSettle();
    expect(find.byType(FullDesktopDialog<bool>), findsOneWidget);
    expect(find.textContaining('1234.56'), findsNWidgets(2));
    // Background graph changes while confirmation is open must not admit stale execution.
    d['nodes'][1]['parameters']['threshold'] = 0;
    await tester.tap(find.widgetWithText(FilledButton, '开始回测'));
    await tester.pumpAndSettle();
    expect(service.started, isNull);
    expect(find.textContaining('确认期间草稿或配置已修改'), findsOneWidget);
    await tester.tap(find.text('开始回测'));
    await tester.pumpAndSettle();
    await tester.tap(find.widgetWithText(FilledButton, '开始回测'));
    await tester.pumpAndSettle();
    expect(service.started!['account']['initial_cash'], '1234.56');
    final model = jsonDecode(service.started!['model']);
    expect(model['graph']['metadata']['visual_source_id'], isNotEmpty);
    expect(
        model['outputs'][0]['expression']['binary']['right']['literal']
            ['value'],
        '0');
    d['nodes'][4]['parameters']['orderType'] = '限价单';
    await tester.tap(find.text('开始回测'));
    await tester.pumpAndSettle();
    expect(find.byType(FullDesktopDialog<bool>), findsNothing);
    expect(find.textContaining('不支持限价'), findsOneWidget);
    expect(tester.takeException(), isNull);
  });
  testWidgets(
      'invalid graph capital survives panel recreation without starting',
      (tester) async {
    final service = _RenderService(), d = visual.graph();
    Widget app() => GetMaterialApp(
        locale: const Locale('zh', 'CN'),
        home: Scaffold(
            body: FqeWorkbenchPanel(owner: service, visualDocument: () => d)));
    await tester.pumpWidget(app());
    final capital = find.widgetWithText(TextField, '初始资金（报价币，精确十进制）');
    await tester.ensureVisible(capital);
    await tester.enterText(capital, 'invalid-capital');
    await tester.pumpWidget(const SizedBox());
    await tester.pumpAndSettle();
    await tester.pumpWidget(app());
    await tester.pumpAndSettle();
    expect(find.text('invalid-capital'), findsOneWidget);
    await tester.tap(find.text('开始回测'));
    await tester.pumpAndSettle();
    expect(service.started, isNull);
    expect(find.byType(FullDesktopDialog<bool>), findsNothing);
    expect(tester.takeException(), isNull);
  });
  testWidgets('portable parameter changed during preflight rejects old input',
      (tester) async {
    final service = _RenderService()..preparation = Completer<void>();
    await tester.pumpWidget(GetMaterialApp(
        locale: const Locale('zh', 'CN'),
        home: Scaffold(body: FqeWorkbenchPanel(owner: service))));
    await tester.enterText(find.byType(TextFormField).first, '90');
    await tester.tap(find.text('开始回测'));
    await tester.pump();
    await tester.enterText(find.byType(TextFormField).first, '80');
    service.preparation!.complete();
    await tester.pumpAndSettle();
    expect(service.started, isNull);
    expect(find.byType(FullDesktopDialog<bool>), findsNothing);
    expect(find.textContaining('校验期间草稿或配置已修改'), findsOneWidget);
    expect(find.text('80'), findsOneWidget);
    expect(tester.takeException(), isNull);
  });
  testWidgets(
      'existing editor keeps canvas/code/parameters and mounts engine inside backtest/run',
      (tester) async {
    tester.view.physicalSize = const Size(1300, 900);
    tester.view.devicePixelRatio = 1;
    addTearDown(tester.view.resetPhysicalSize);
    addTearDown(tester.view.resetDevicePixelRatio);
    final d = VisualStrategyDocument();
    addTearDown(d.dispose);
    await tester.pumpWidget(GetMaterialApp(
        locale: const Locale('zh', 'CN'),
        home: Scaffold(
            body:
                QuantVisualStrategyEditor(document: d, onSave: (_) async {}))));
    expect(find.text('本地引擎'), findsNothing);
    await tester.tap(find.text('回测配置'));
    await tester.pumpAndSettle();
    expect(find.byType(FqeWorkbenchPanel), findsOneWidget);
    await tester.tap(find.text('运行配置'));
    await tester.pumpAndSettle();
    expect(
        tester
            .widget<FqeWorkbenchPanel>(find.byType(FqeWorkbenchPanel))
            .showResults,
        isTrue);
    expect(find.text('代码编辑'), findsOneWidget);
    expect(find.text('参数定义'), findsOneWidget);
    expect(tester.takeException(), isNull);
  });
  testWidgets(
      'offline research entry opens editor without login services and saves an independent draft',
      (tester) async {
    tester.view.physicalSize = const Size(1360, 1000);
    tester.view.devicePixelRatio = 1;
    addTearDown(tester.view.resetPhysicalSize);
    addTearDown(tester.view.resetDevicePixelRatio);
    Map<String, Object>? saved;
    await tester.pumpWidget(GetMaterialApp(
        locale: const Locale('zh', 'CN'),
        home: Scaffold(
            body: FqeOfflineResearchButton(
                readDraft: () => null,
                saveDraft: (d) async {
                  saved = d;
                }))));
    await tester.tap(find.byKey(const ValueKey('offline-research-entry')));
    await tester.pumpAndSettle();
    expect(find.text('本地策略研究'), findsOneWidget);
    expect(find.byType(QuantVisualStrategyEditor), findsOneWidget);
    await tester.tap(find.text('保存草稿'));
    await tester.pumpAndSettle();
    expect(saved, isNotNull);
    await tester.tap(find.text('回测配置'));
    await tester.pumpAndSettle();
    expect(find.byType(FqeWorkbenchPanel), findsOneWidget);
    await tester.tap(find.text('关闭研究窗口'));
    await tester.pumpAndSettle();
    expect(find.byType(QuantVisualStrategyEditor), findsNothing);
    expect(Get.isRegistered<Object>(), isFalse);
    expect(tester.takeException(), isNull);
  });
}
